export type AchievementCategory = 'accuracy' | 'streak' | 'speed' | 'completion' | 'special';

export interface Achievement {
  id: string;
  title: string;
  description: string;
  icon: string;             // Material icon name
  category: AchievementCategory;
  requirement: number;      // Value needed to unlock
  progress: number;         // Current progress
  unlocked: boolean;
  unlockedAt?: Date;
  xpReward: number;
}

/**
 * Achievement definitions
 */
export const ACHIEVEMENTS: Omit<Achievement, 'progress' | 'unlocked' | 'unlockedAt'>[] = [
  // Accuracy Achievements
  {
    id: 'perfect_10',
    title: 'Perfect!',
    description: '10 perfect notes in a row',
    icon: 'looks_one',
    category: 'accuracy',
    requirement: 10,
    xpReward: 50
  },
  {
    id: 'perfect_50',
    title: 'Sharpshooter',
    description: '50 perfect notes in a row',
    icon: 'star',
    category: 'accuracy',
    requirement: 50,
    xpReward: 200
  },
  {
    id: 'flawless_lesson',
    title: 'Flawless',
    description: 'Complete a lesson with 100% accuracy',
    icon: 'emoji_events',
    category: 'accuracy',
    requirement: 1,
    xpReward: 150
  },

  // Streak Achievements
  {
