  },
  {
    id: 'streak_30',
    title: 'Dedicated',
    description: '30-day practice streak',
    icon: 'whatshot',
    category: 'streak',
    requirement: 30,
    xpReward: 500
  },
  {
    id: 'streak_100',
    title: 'Legend',
    description: '100-day practice streak',
    icon: 'military_tech',
    category: 'streak',
    requirement: 100,
