  },
  {
    id: 'lessons_10',
    title: 'Learner',
    description: 'Complete 10 lessons',
    icon: 'school',
    category: 'completion',
    requirement: 10,
    xpReward: 300
  },
  {
    id: 'lessons_50',
    title: 'Scholar',
