    category: 'special',
    requirement: 1,
    xpReward: 25
  },
  {
    id: 'marathon',
    title: 'Marathon',
    description: '2 hours of practice in one session',
    icon: 'timer',
    category: 'special',
    requirement: 1,
    xpReward: 200
  }
