            case 'Close':
                return 'yellow';
            case 'Wrong':
                return 'red';
        }
    },

    /**
     * Get Material icon for feedback type
     */
    getIcon(feedback: FeedbackType): string {
        switch (feedback) {
            case 'Perfect':
                return 'star';
            case 'Good':
                return 'check_circle';
            case 'Close':
                return 'help_outline';
            case 'Wrong':
                return 'cancel';
        }
    },

    /**
