import { Injectable, signal, inject } from '@angular/core';
import { Achievement, ACHIEVEMENTS } from '../models/achievement.model';
import { ProgressService } from './progress.service';
import { SoundService } from './sound.service';

/**
 * Achievement Service
 * Manages unlockable achievements and badges
 */
@Injectable({
  providedIn: 'root'
})
export class AchievementService {
  private progressService = inject(ProgressService);
  private soundService = inject(SoundService);

  // State
  private readonly _achievements = signal<Achievement[]>([]);
  private readonly _recentUnlock = signal<Achievement | null>(null);

  // Public signals
  readonly achievements = this._achievements.asReadonly();
  readonly recentUnlock = this._recentUnlock.asReadonly();

  // Counters for achievement tracking
  private perfectNoteStreak = 0;
  private lessonsCompleted = 0;
  private practiceSessionStart: Date | null = null;

  constructor() {
    this.loadAchievements();
  }

  /**
   * Check and update progress for an achievement
   */
  checkAchievement(achievementId: string, currentValue: number): void {
    const achievements = this._achievements();
    const achievement = achievements.find(a => a.id === achievementId);

    if (!achievement || achievement.unlocked) return;

    // Update progress
    achievement.progress = Math.min(currentValue, achievement.requirement);

    // Check if unlocked
    if (achievement.progress >= achievement.requirement) {
      this.unlockAchievement(achievement);
    }

    this._achievements.set([...achievements]);
    this.saveAchievements();
  }

  /**
   * Unlock an achievement
   */
  private unlockAchievement(achievement: Achievement): void {
    achievement.unlocked = true;
    achievement.unlockedAt = new Date();

    // Play achievement sound
    this.soundService.play('achievement');

    // Award XP
    this.progressService.awardXP(achievement.xpReward, `Achievement: ${achievement.title}`);

    // Show notification
    this._recentUnlock.set(achievement);
    console.log(`[Achievement] Unlocked: ${achievement.title}`);

    // Clear notification after 5 seconds
    setTimeout(() => {
      if (this._recentUnlock() === achievement) {
        this._recentUnlock.set(null);
      }
    }, 5000);

    this.saveAchievements();
  }

  /**
   * Track perfect note streak
   */
  onPerfectNote(): void {
    this.perfectNoteStreak++;

    // Check achievements
    this.checkAchievement('perfect_10', this.perfectNoteStreak);
    this.checkAchievement('perfect_50', this.perfectNoteStreak);
  }

  /**
   * Reset perfect note streak
   */
  onWrongNote(): void {
    this.perfectNoteStreak = 0;
  }

  /**
   * Track lesson completion
   */
  onLessonComplete(accuracy: number): void {
    this.lessonsCompleted++;

    // Check completion achievements
    this.checkAchievement('first_lesson', this.lessonsCompleted);
    this.checkAchievement('lessons_10', this.lessonsCompleted);
    this.checkAchievement('lessons_50', this.lessonsCompleted);

    // Check flawless
    if (accuracy >= 100) {
      this.checkAchievement('flawless_lesson', 1);
    }
  }

  /**
   * Track practice session start
   */
  startPracticeSession(): void {
    this.practiceSessionStart = new Date();

    // Check time-based achievements
    const hour = this.practiceSessionStart.getHours();
    if (hour >= 0 && hour < 6) {
      this.checkAchievement('early_bird', 1);
    } else if (hour === 0) {
      this.checkAchievement('night_owl', 1);
    }
  }

  /**
   * Track practice session end
   */
  endPracticeSession(): void {
    if (!this.practiceSessionStart) return;

    const sessionDuration = Date.now() - this.practiceSessionStart.getTime();
    const twoHours = 2 * 60 * 60 * 1000;

    if (sessionDuration >= twoHours) {
      this.checkAchievement('marathon', 1);
    }

    this.practiceSessionStart = null;
  }

  /**
   * Update daily streak achievement
   */
  updateStreakAchievements(streakDays: number): void {
    this.checkAchievement('streak_5', streakDays);
    this.checkAchievement('streak_30', streakDays);
    this.checkAchievement('streak_100', streakDays);
  }

  /**
   * Get achievements by category
   */
  getByCategory(category: string): Achievement[] {
    return this._achievements().filter(a => a.category === category);
  }

  /**
   * Get unlocked achievements
   */
  getUnlocked(): Achievement[] {
    return this._achievements().filter(a => a.unlocked);
  }

  /**
   * Get locked achievements
   */
  getLocked(): Achievement[] {
    return this._achievements().filter(a => !a.unlocked);
  }

  /**
   * Reset all achievements (for testing)
   */
  reset(): void {
    const fresh = ACHIEVEMENTS.map(def => ({
      ...def,
      progress: 0,
      unlocked: false
    }));

    this._achievements.set(fresh);
    this.perfectNoteStreak = 0;
    this.lessonsCompleted = 0;
    this.saveAchievements();
  }

  /**
   * Load achievements from localStorage
   */
  private loadAchievements(): void {
    const saved = localStorage.getItem('achievements');

    if (saved) {
      try {
        const data = JSON.parse(saved) as Achievement[];
        this._achievements.set(data);
        return;
      } catch (e) {
        console.error('[Achievement] Failed to load achievements:', e);
      }
    }

    // Initialize with defaults
    const fresh = ACHIEVEMENTS.map(def => ({
      ...def,
      progress: 0,
      unlocked: false
    }));

    this._achievements.set(fresh);
  }

  /**
   * Save achievements to localStorage
   */
  private saveAchievements(): void {
    localStorage.setItem('achievements', JSON.stringify(this._achievements()));
  }
}

import { Injectable, computed, inject, signal } from '@angular/core';
import { EvaluationResult, SessionStats } from '../models';
import { TauriService } from './tauri.service';
import { ProgressService } from './progress.service';
import { AchievementService } from './achievement.service';
import { SoundService } from './sound.service';
import { PianoSoundService } from './piano-sound.service';

/**
 * Evaluation Service
 * Handles note checking and session statistics
 * Communicates with Rust evaluation backend
 */
@Injectable({
    providedIn: 'root'
})
export class EvaluationService {
    private tauri = inject(TauriService);
    private progressService = inject(ProgressService);
    private achievementService = inject(AchievementService);
    private soundService = inject(SoundService);
    private pianoService = inject(PianoSoundService);

    // Reactive signals for UI
    private _lastResult = signal<EvaluationResult | null>(null);
    private _stats = signal<SessionStats | null>(null);
    private _isEvaluating = signal(false);

    // Public computed signals
    readonly lastResult = this._lastResult.asReadonly();
    readonly stats = this._stats.asReadonly();
    readonly isEvaluating = this._isEvaluating.asReadonly();

    // Computed helpers
    readonly currentStreak = computed(() => this._stats()?.current_streak ?? 0);
    readonly accuracy = computed(() => this._stats()?.accuracy ?? 0);
    readonly totalNotes = computed(() => this._stats()?.total_notes ?? 0);

    /**
     * Initialize - listen for evaluation events from backend
     */
    async initialize(): Promise<void> {
        await this.tauri.listen<EvaluationResult>('note_evaluated', (result) => {
            this._lastResult.set(result);
            console.log('[Evaluation] Note evaluated:', result.feedback, result.message);
        });

        // Load initial stats
        await this.refreshStats();
    }

    /**
     * Check a single note against expected
     * Full evaluation with timing and duration
     */
    async checkNote(
        playedMidi: number,
        expectedMidi: number,
        playedTimeMs?: number,
        expectedTimeMs?: number,
        playedDurationMs?: number,
        expectedDurationMs?: number
    ): Promise<EvaluationResult> {
        this._isEvaluating.set(true);
        try {
            const result = await this.tauri.invoke<EvaluationResult>('check_note', {
                playedMidi: playedMidi,
                expectedMidi: expectedMidi,
                playedTimeMs: playedTimeMs,
                expectedTimeMs: expectedTimeMs,
                playedDurationMs: playedDurationMs,
                expectedDurationMs: expectedDurationMs
            });

            this._lastResult.set(result);
            await this.refreshStats();
            return result;
        } finally {
            this._isEvaluating.set(false);
        }
    }

    /**
     * Check pitch only (for Waiting mode)
     * Ignores timing and duration
     */
    async checkPitch(playedMidi: number, expectedMidi: number): Promise<EvaluationResult> {
        this._isEvaluating.set(true);
        try {
            const result = await this.tauri.invoke<EvaluationResult>('check_pitch', {
                playedMidi: playedMidi,
                expectedMidi: expectedMidi
            });

            this._lastResult.set(result);
            await this.refreshStats();

            // Award XP based on result
            const isPerfect = result.score >= 100;
            this.progressService.awardNoteXP(result.pitch_correct, isPerfect);

            // Track achievements and play sounds
            if (result.pitch_correct && isPerfect) {
                this.achievementService.onPerfectNote();
                // Play actual piano note for correct notes (satisfying feedback)
                this.pianoService.playNote(playedMidi, 100, 0.5);
            } else if (result.pitch_correct) {
                // Play piano note for correct notes
                this.pianoService.playNote(playedMidi, 80, 0.4);
            } else {
                this.achievementService.onWrongNote();
                // For wrong notes, play a subtle error sound (not the harsh beep)
                this.soundService.play('wrongNote');
            }

            // Play combo sound for streaks (keep this celebratory sound)
            const streak = this.currentStreak();
            if (streak >= 10 && streak % 5 === 0) {
                this.soundService.play('combo');
            }

            return result;
        } finally {
            this._isEvaluating.set(false);
        }
    }

    /**
     * Check if a chord matches expected notes
     * All notes must be correct for success
     */
    async checkChord(playedMidis: number[], expectedMidis: number[]): Promise<EvaluationResult[]> {
        const results: EvaluationResult[] = [];

        // Match each played note to nearest expected
        const remainingExpected = [...expectedMidis];

        for (const played of playedMidis) {
            // Find exact match first
            const exactIndex = remainingExpected.indexOf(played);
            if (exactIndex !== -1) {
                const result = await this.checkPitch(played, remainingExpected[exactIndex]);
                results.push(result);
                remainingExpected.splice(exactIndex, 1);
            } else if (remainingExpected.length > 0) {
                // Check against first remaining expected (will be wrong)
                const result = await this.checkPitch(played, remainingExpected[0]);
                results.push(result);
            }
        }

        return results;
    }

    /**
     * Get current session statistics
     */
    async getStats(): Promise<SessionStats> {
        const stats = await this.tauri.invoke<SessionStats>('get_stats');
        this._stats.set(stats);
        return stats;
    }

    /**
     * Refresh stats from backend
     */
    async refreshStats(): Promise<void> {
        try {
            await this.getStats();
        } catch (error) {
            console.error('[Evaluation] Failed to refresh stats:', error);
        }
    }

    /**
     * Reset all session statistics
     */
    async resetStats(): Promise<void> {
        await this.tauri.invoke('reset_stats');
        this._stats.set(null);
        this._lastResult.set(null);
    }

    /**
     * Award lesson completion XP
     * Call this when a lesson is completed
     */
    awardLessonCompletionXP(): void {
        const stats = this._stats();
        if (stats) {
            this.progressService.awardLessonXP(stats.accuracy);
            this.achievementService.onLessonComplete(stats.accuracy);
        }
    }

    /**
     * Clean up listeners
     */
    async cleanup(): Promise<void> {
        await this.tauri.unlisten('note_evaluated');
    }
}

import { computed, Injectable, signal } from '@angular/core';
import { LessonDTO, LessonMetadataDTO } from '../models/lesson.model';
import { TauriService } from './tauri.service';

/**
 * Lesson management service
 * Calls existing Rust backend commands for lesson loading
 */
@Injectable({
    providedIn: 'root'
})
export class LessonService {
    // Reactive state using Angular signals
    private readonly _currentLesson = signal<LessonDTO | null>(null);
    private readonly _availableLessons = signal<LessonMetadataDTO[]>([]);
    private readonly _loading = signal(false);
    private readonly _error = signal<string | null>(null);

    // Public readonly signals
    readonly currentLesson = this._currentLesson.asReadonly();
    readonly availableLessons = this._availableLessons.asReadonly();
    readonly loading = this._loading.asReadonly();
    readonly error = this._error.asReadonly();

    // Computed values
    readonly hasLesson = computed(() => this._currentLesson() !== null);
    readonly lessonCount = computed(() => this._availableLessons().length);

    constructor(private tauri: TauriService) { }

    /**
     * Load a specific lesson by ID
     * Calls: src-tauri/src/commands/lesson.rs::load_lesson
     */
    async loadLesson(lessonId: string): Promise<LessonDTO> {
        this._loading.set(true);
        this._error.set(null);

        try {
            const lesson = await this.tauri.invoke<LessonDTO>('load_lesson', { lessonId });
            this._currentLesson.set(lesson);
            console.log(`[LessonService] Loaded lesson: ${lesson.title} (${lesson.measures.length} measures)`);
            return lesson;
        } catch (err) {
            const message = `Failed to load lesson "${lessonId}": ${err}`;
            this._error.set(message);
            console.error(`[LessonService] ${message}`);
            throw err;
        } finally {
            this._loading.set(false);
        }
    }

    /**
     * Get list of all available lessons
     * Calls: src-tauri/src/commands/lesson.rs::list_lessons
     */
    async listLessons(): Promise<LessonMetadataDTO[]> {
        this._loading.set(true);
        this._error.set(null);

        try {
            const lessons = await this.tauri.invoke<LessonMetadataDTO[]>('list_lessons');
            this._availableLessons.set(lessons);
            console.log(`[LessonService] Found ${lessons.length} lessons`);
            return lessons;
        } catch (err) {
            const message = `Failed to list lessons: ${err}`;
            this._error.set(message);
            console.error(`[LessonService] ${message}`);
            throw err;
        } finally {
            this._loading.set(false);
        }
    }

    /**
     * Clear current lesson
     */
    clearLesson(): void {
        this._currentLesson.set(null);
    }

    /**
     * Get current measure count
     */
    getMeasureCount(): number {
        const lesson = this._currentLesson();
        return lesson ? lesson.measures.length : 0;
    }

    /**
     * Get total notes in current lesson
     */
    getTotalNotes(): number {
        const lesson = this._currentLesson();
        if (!lesson) return 0;
        return lesson.measures.reduce((sum, m) => sum + m.notes.length, 0);
    }
}

