import { computed, inject, Injectable, signal } from '@angular/core';
import { MatSnackBar } from '@angular/material/snack-bar';
import { MidiChord, MidiDevice, midiToNoteName } from '../models/midi-event.model';
import { TauriService } from './tauri.service';

/**
 * MIDI service for handling keyboard input
 * Connects to Rust backend for native MIDI access via Tauri
 */
@Injectable({
    providedIn: 'root'
})
export class MidiService {
    private snackBar = inject(MatSnackBar);

    // Reactive state
    private readonly _devices = signal<MidiDevice[]>([]);
    private readonly _selectedDevice = signal<MidiDevice | null>(null);
    private readonly _activeNotes = signal<Set<number>>(new Set());
    private readonly _connected = signal(false);
    private readonly _error = signal<string | null>(null);
    private readonly _lastChord = signal<MidiChord | null>(null);

    // Public readonly signals
    readonly devices = this._devices.asReadonly();
    readonly selectedDevice = this._selectedDevice.asReadonly();
    readonly activeNotes = this._activeNotes.asReadonly();
    readonly connected = this._connected.asReadonly();
    readonly error = this._error.asReadonly();
    readonly lastChord = this._lastChord.asReadonly();

    // Computed values
    readonly hasDevices = computed(() => this._devices().length > 0);
    readonly activeNoteNames = computed(() => {
        const notes = this._activeNotes();
        return Array.from(notes).map(midiToNoteName);
    });

    constructor(private tauri: TauriService) {
        this.setupEventListeners();
    }

    /**
     * Set up Tauri event listeners for MIDI events
     */
    private async setupEventListeners(): Promise<void> {
        if (!this.tauri.isTauri()) {
            console.log('[MidiService] Not in Tauri environment, skipping event setup');
            return;
        }

        // Listen for chord detected events from Rust backend
        // Event: midi_chord_detected with MidiChord payload
        await this.tauri.listen<MidiChord>('midi_chord_detected', (chord) => {
            this.handleChordDetected(chord);
        });

        // Listen for note-off events from Rust backend
        // Event: midi_note_off with note number payload
        await this.tauri.listen<number>('midi_note_off', (note) => {
            this.handleNoteOff(note);
        });

        console.log('[MidiService] Event listeners set up');
    }

    /**
     * Handle chord detected event from backend (note on)
     */
    private handleChordDetected(chord: MidiChord): void {
        // Add the chord notes to active notes (don't replace, add to existing)
        const currentNotes = new Set(this._activeNotes());
        for (const note of chord.notes) {
            currentNotes.add(note);
        }
        this._activeNotes.set(currentNotes);
        this._lastChord.set(chord);

        console.log(`[MIDI] Note On: ${chord.notes.map(midiToNoteName).join('+')} (${chord.hand} hand)`);
    }

    /**
     * Handle note-off event from backend
     */
    private handleNoteOff(note: number): void {
        const currentNotes = new Set(this._activeNotes());
        currentNotes.delete(note);
        this._activeNotes.set(currentNotes);

        console.log(`[MIDI] Note Off: ${midiToNoteName(note)}`);
    }

    /**
     * List available MIDI devices
     * Calls: src-tauri/src/commands/midi.rs::get_midi_devices
     */
    async listDevices(): Promise<void> {
        try {
            const devices = await this.tauri.invoke<MidiDevice[]>('get_midi_devices');
            this._devices.set(devices);
            console.log(`[MidiService] Found ${devices.length} MIDI devices`);
        } catch (err) {
            this._error.set(`Failed to list MIDI devices: ${err}`);
            console.error('[MidiService]', err);
        }
    }

    /**
     * Connect to a MIDI device
     * Calls: src-tauri/src/commands/midi.rs::start_midi_listening
     */
    async connect(deviceId: string, showNotification = true): Promise<void> {
        try {
            await this.tauri.invoke('start_midi_listening', { deviceId });
            const device = this._devices().find(d => d.id === deviceId);
            if (device) {
                this._selectedDevice.set(device);
                this._connected.set(true);
                console.log(`[MidiService] Connected to ${device.name}`);

                if (showNotification) {
                    this.snackBar.open(`🎹 Connected to ${device.name}`, 'Dismiss', {
                        duration: 3000,
                        horizontalPosition: 'center',
                        verticalPosition: 'bottom',
                        panelClass: ['success-snackbar']
                    });
                }
            }
        } catch (err) {
            this._error.set(`Failed to connect: ${err}`);
            console.error('[MidiService]', err);

            if (showNotification) {
                this.snackBar.open(`❌ Failed to connect to MIDI device`, 'Dismiss', {
                    duration: 4000,
                    horizontalPosition: 'center',
                    verticalPosition: 'bottom',
                    panelClass: ['error-snackbar']
                });
            }
        }
    }

    /**
     * Disconnect from current MIDI device
     */
    async disconnect(showNotification = true): Promise<void> {
        try {
            const deviceName = this._selectedDevice()?.name || 'MIDI device';
            await this.tauri.invoke('stop_midi_listening');
            this._selectedDevice.set(null);
            this._connected.set(false);
            this._activeNotes.set(new Set());
            this._lastChord.set(null);
            console.log('[MidiService] Disconnected');

            if (showNotification) {
                this.snackBar.open(`Disconnected from ${deviceName}`, 'OK', {
                    duration: 2000,
                    horizontalPosition: 'center',
                    verticalPosition: 'bottom'
                });
            }
        } catch (err) {
            console.error('[MidiService] Disconnect error:', err);
        }
    }

    /**
     * Auto-connect to first available MIDI device
     */
    async autoConnect(): Promise<boolean> {
        await this.listDevices();
        const devices = this._devices();

        if (devices.length > 0) {
            const firstDevice = devices[0];
            await this.connect(firstDevice.id, true);
            return true;
        }

        return false;
    }

    /**
     * Check if a specific note is currently pressed
     */
    isNoteActive(midi: number): boolean {
        return this._activeNotes().has(midi);
    }
}

import { Injectable, signal } from '@angular/core';

/**
 * Piano Sound Service
 * Synthesizes realistic piano sounds using Web Audio API
 * Uses multiple oscillators with harmonics and ADSR envelope
 */
@Injectable({
  providedIn: 'root'
})
export class PianoSoundService {
  private audioContext: AudioContext | null = null;
  private masterGain: GainNode | null = null;
  private activeNotes: Map<number, { oscillators: OscillatorNode[], gain: GainNode }> = new Map();

  // Settings
  private _enabled = signal(true);
  private _volume = signal(0.7);

  readonly enabled = this._enabled.asReadonly();
  readonly volume = this._volume.asReadonly();

  // Piano harmonic structure (relative amplitudes)
  private readonly harmonics = [
    { ratio: 1, amplitude: 1.0 },      // Fundamental
    { ratio: 2, amplitude: 0.5 },      // 2nd harmonic
    { ratio: 3, amplitude: 0.25 },     // 3rd harmonic
    { ratio: 4, amplitude: 0.125 },    // 4th harmonic
    { ratio: 5, amplitude: 0.0625 },   // 5th harmonic
    { ratio: 6, amplitude: 0.03 },     // 6th harmonic
  ];

  constructor() {
    // Initialize on first user interaction
    if (typeof window !== 'undefined') {
      const initHandler = () => {
        this.initAudio();
        document.removeEventListener('click', initHandler);
        document.removeEventListener('keydown', initHandler);
      };
      document.addEventListener('click', initHandler);
      document.addEventListener('keydown', initHandler);
    }
  }

  /**
   * Initialize Web Audio API context
   */
  initAudio(): void {
    if (this.audioContext) return;

    this.audioContext = new AudioContext();
    this.masterGain = this.audioContext.createGain();
    this.masterGain.connect(this.audioContext.destination);
    this.masterGain.gain.value = this._volume();

    console.log('[PianoSound] Audio context initialized');
  }

  /**
   * Convert MIDI note number to frequency (Hz)
   * A4 (MIDI 69) = 440 Hz
   */
  private midiToFrequency(midi: number): number {
    return 440 * Math.pow(2, (midi - 69) / 12);
  }

  /**
   * Play a piano note
   * @param midi MIDI note number (21-108 for standard piano)
   * @param velocity Note velocity (0-127, default 100)
   * @param duration Duration in seconds (0 = sustained until noteOff)
   */
  playNote(midi: number, velocity: number = 100, duration: number = 0): void {
    if (!this._enabled() || !this.audioContext || !this.masterGain) {
      this.initAudio();
      if (!this.audioContext || !this.masterGain) return;
    }

    // Resume context if suspended (browser autoplay policy)
    if (this.audioContext.state === 'suspended') {
      this.audioContext.resume();
    }

    // Stop any existing note at this pitch
    this.stopNote(midi);

    const now = this.audioContext.currentTime;
    const frequency = this.midiToFrequency(midi);
    const velocityScale = velocity / 127;

    // Create envelope gain node
    const envelopeGain = this.audioContext.createGain();
    envelopeGain.connect(this.masterGain);

    // Create oscillators for each harmonic
    const oscillators: OscillatorNode[] = [];

    this.harmonics.forEach(({ ratio, amplitude }) => {
      const osc = this.audioContext!.createOscillator();
      const oscGain = this.audioContext!.createGain();

      // Use different wave types for different harmonics
      if (ratio === 1) {
        osc.type = 'sine';
      } else if (ratio <= 3) {
        osc.type = 'triangle';
      } else {
        osc.type = 'sine';
      }

      osc.frequency.value = frequency * ratio;

      // Scale amplitude based on harmonic and velocity
      oscGain.gain.value = amplitude * velocityScale * 0.15;

      osc.connect(oscGain);
      oscGain.connect(envelopeGain);

      osc.start(now);
      oscillators.push(osc);
    });

    // ADSR Envelope for piano-like sound
    // Attack: Very fast for piano (5-10ms)
    // Decay: Medium (100-300ms)
    // Sustain: Lower than peak (0.3-0.5)
    // Release: Medium (200-500ms)

    const attackTime = 0.008;  // 8ms attack
    const decayTime = 0.15;    // 150ms decay
    const sustainLevel = 0.4;  // 40% sustain
    const releaseTime = 0.3;   // 300ms release

    // Set initial value and apply envelope
    envelopeGain.gain.setValueAtTime(0, now);
    envelopeGain.gain.linearRampToValueAtTime(1, now + attackTime);
    envelopeGain.gain.exponentialRampToValueAtTime(sustainLevel, now + attackTime + decayTime);

    // Store active note for later release
    this.activeNotes.set(midi, { oscillators, gain: envelopeGain });

    // If duration specified, auto-stop
    if (duration > 0) {
      setTimeout(() => this.stopNote(midi), duration * 1000);
    }
  }

  /**
   * Stop a playing note with release envelope
   */
  stopNote(midi: number): void {
    const note = this.activeNotes.get(midi);
    if (!note || !this.audioContext) return;

    const now = this.audioContext.currentTime;
    const releaseTime = 0.3;

    // Apply release envelope
    note.gain.gain.cancelScheduledValues(now);
    note.gain.gain.setValueAtTime(note.gain.gain.value, now);
    note.gain.gain.exponentialRampToValueAtTime(0.001, now + releaseTime);

    // Stop and cleanup after release
    setTimeout(() => {
      note.oscillators.forEach(osc => {
        try {
          osc.stop();
          osc.disconnect();
        } catch (e) {
          // Already stopped
        }
      });
      note.gain.disconnect();
    }, releaseTime * 1000 + 50);

    this.activeNotes.delete(midi);
  }

  /**
   * Play multiple notes simultaneously (chord)
   */
  playChord(midiNotes: number[], velocity: number = 100, duration: number = 0): void {
    midiNotes.forEach(midi => this.playNote(midi, velocity, duration));
  }

  /**
   * Stop multiple notes
   */
  stopChord(midiNotes: number[]): void {
    midiNotes.forEach(midi => this.stopNote(midi));
  }

  /**
   * Stop all playing notes
   */
  stopAll(): void {
    this.activeNotes.forEach((_, midi) => this.stopNote(midi));
    this.activeNotes.clear();
  }

  /**
   * Play a note for a specific duration (for playback)
   */
  async playNoteTimed(midi: number, durationMs: number, velocity: number = 100): Promise<void> {
    this.playNote(midi, velocity);

    return new Promise(resolve => {
      setTimeout(() => {
        this.stopNote(midi);
        resolve();
      }, durationMs);
    });
  }

  /**
   * Play a chord for a specific duration (for playback)
   */
  async playChordTimed(midiNotes: number[], durationMs: number, velocity: number = 100): Promise<void> {
    midiNotes.forEach(midi => this.playNote(midi, velocity));

    return new Promise(resolve => {
      setTimeout(() => {
        midiNotes.forEach(midi => this.stopNote(midi));
        resolve();
      }, durationMs);
    });
  }

  /**
   * Toggle sound on/off
   */
  toggle(): void {
    this._enabled.set(!this._enabled());
  }

  /**
   * Set volume (0-1)
   */
  setVolume(volume: number): void {
    const clamped = Math.max(0, Math.min(1, volume));
    this._volume.set(clamped);

    if (this.masterGain) {
      this.masterGain.gain.value = clamped;
    }
  }

  /**
   * Get note name for display
   */
  getNoteNameFromMidi(midi: number): string {
    const noteNames = ['C', 'C#', 'D', 'D#', 'E', 'F', 'F#', 'G', 'G#', 'A', 'A#', 'B'];
    const octave = Math.floor(midi / 12) - 1;
    const note = noteNames[midi % 12];
    return `${note}${octave}`;
  }
}

