    width: 100%;
}

.control-bar {
    display: flex;
    align-items: center;
    gap: 1rem;
    padding: 0 1rem;
    height: 100%;
    background: linear-gradient(180deg, #16213e 0%, #1a1a2e 100%);
    border-bottom: 2px solid #3B82F6;
}

.restart-btn {
    color: white;
}

.play-btn {
    color: white;
}

.auto-play-btn {
    color: rgba(255, 255, 255, 0.7);
    transition: all 0.2s ease;

    &:hover {
        color: #22c55e;
    }

    &.active {
        color: #22c55e;
        animation: pulse 1.5s infinite;
    }
}

@keyframes pulse {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.6; }
}

.progress-section {
    flex: 1;
    display: flex;
    align-items: center;
    gap: 0.75rem;

    .progress-container {
        flex: 1;
        display: flex;
        flex-direction: column;
        gap: 4px;
    }

    .progress-track {
        position: relative;
        height: 12px;
        background: rgba(255, 255, 255, 0.1);
        border-radius: 6px;
        border: 1px solid rgba(255, 255, 255, 0.2);
        overflow: visible;
    }

    .progress-fill {
        height: 100%;
        background: linear-gradient(90deg, #22c55e 0%, #3B82F6 50%, #8B5CF6 100%);
        border-radius: 6px;
        transition: width 0.1s ease-out;
        box-shadow: 0 0 8px rgba(59, 130, 246, 0.5);
    }

    .progress-indicator {
        position: absolute;
        top: 50%;
        transform: translate(-50%, -50%);
        z-index: 2;
        transition: left 0.1s ease-out;
    }

    .indicator-dot {
        width: 18px;
        height: 18px;
        background: white;
        border-radius: 50%;
        border: 3px solid #3B82F6;
        box-shadow: 0 0 10px rgba(59, 130, 246, 0.8), 0 2px 4px rgba(0, 0, 0, 0.3);
    }

    .progress-labels {
        display: flex;
        justify-content: space-between;
        font-size: 0.65rem;
        color: rgba(255, 255, 255, 0.4);
        padding: 0 2px;
    }

    .progress-text {
        min-width: 50px;
        text-align: right;
        font-size: 1rem;
        font-weight: 600;
        color: white;
        background: rgba(59, 130, 246, 0.3);
        padding: 4px 8px;
        border-radius: 4px;
    }
}

.tempo-section {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    color: white;

    mat-slider {
        width: 100px;
    }

    .tempo-text {
        min-width: 45px;
        font-size: 0.9rem;
    }
}

mat-button-toggle-group {
    border: 1px solid rgba(255, 255, 255, 0.3);
}

